// Actionability Gate - Kernlogik (Audit-Konzept 2026-08-24, Kap. 13).
// Vier Klassen, in dieser Reihenfolge geprueft (jede Stufe ist ein Ausschluss-
// Filter fuer die naechste, genau wie in Kap. 13 beschrieben):
//   IGNORE  - irrelevant, Duplikat, oder Datenqualitaet unter Schwelle
//   INFO    - kein konkreter Tickerbezug (Makro/Markt), ODER Evidenz nicht ausreichend
//   WATCH   - Rest-Faelle: Relevanz+Ticker+Evidenz da, aber (noch) nicht alarmwuerdig
//   ALERT   - Tickerbezug + kein hartes Veto + Regime passt + Evidenz widerspricht
//             nicht klar + ausreichende Evidenzqualitaet + kein Duplikat/Cooldown +
//             technische Bestaetigung vorhanden
//
// WICHTIG (Kap. 18 Schritt 7): "zunaechst nur INFO/WATCH erzeugend, ALERT noch
// nicht scharf" - computed_decision haelt fest, was die Logik ergeben HAETTE,
// decision ist der tatsaechlich wirksame, gedeckelte Wert. Kap. 18 Schritt 9
// hebt die Deckelung auf, ohne diese Logik selbst aendern zu muessen.
function bool(v) { return v === true || v === 'true'; }

const trig = $('Execute Workflow Trigger').first().json;
const ticker = String(trig.ticker || '').trim();
const newsId = trig.news_id !== undefined && trig.news_id !== '' ? trig.news_id : null;
const recommendationId = trig.recommendation_id !== undefined && trig.recommendation_id !== '' ? trig.recommendation_id : null;

const isRelevant = bool(trig.is_relevant);
const isDuplicate = bool(trig.is_duplicate);
const dataQualityOk = trig.data_quality_ok === undefined ? true : bool(trig.data_quality_ok);
const hasTickerBezug = bool(trig.has_ticker_bezug);
const evidenceSufficient = bool(trig.evidence_sufficient);
const hardVetoActive = bool(trig.hard_veto_active);
const regimeFitOk = trig.regime_fit_ok === undefined ? true : bool(trig.regime_fit_ok);
const technicalConfirmation = bool(trig.technical_confirmation);
const evidenceConflicting = bool(trig.evidence_conflicting);
const isCooldownActive = bool(trig.is_cooldown_active);

let computedDecision;
const reasons = {};

if (!isRelevant || isDuplicate || !dataQualityOk) {
  computedDecision = 'IGNORE';
  reasons.ignore_gruende = {
    nicht_relevant: !isRelevant,
    duplikat: isDuplicate,
    datenqualitaet_unzureichend: !dataQualityOk
  };
} else if (!hasTickerBezug || !evidenceSufficient) {
  computedDecision = 'INFO';
  reasons.info_gruende = {
    kein_tickerbezug: !hasTickerBezug,
    evidenz_nicht_ausreichend: !evidenceSufficient
  };
} else {
  const alertConditions = {
    kein_hartes_veto: !hardVetoActive,
    regime_passt: regimeFitOk,
    technische_bestaetigung: technicalConfirmation,
    evidenz_widerspricht_nicht_klar: !evidenceConflicting,
    kein_duplikat_cooldown: !isDuplicate && !isCooldownActive
  };
  const alleErfuellt = Object.values(alertConditions).every(Boolean);
  computedDecision = alleErfuellt ? 'ALERT' : 'WATCH';
  reasons.alert_bedingungen = alertConditions;
}

const alertCapped = computedDecision === 'ALERT';
const decision = alertCapped ? 'WATCH' : computedDecision;
if (alertCapped) reasons.hinweis = 'Logik ergaebe ALERT, aber Kap.18 Schritt 7 deckelt auf WATCH bis Schritt 9 (ALERT scharf schalten) erledigt ist.';

return [{
  json: {
    ticker, news_id: newsId, recommendation_id: recommendationId,
    computed_decision: computedDecision,
    decision,
    alert_capped: alertCapped,
    reasons_json: reasons
  }
}];

// Gibt das Entscheidungsobjekt aus "Werte Actionability-Regeln aus" als
// Rueckgabewert des Subworkflows zurueck - der Insert-Node davor liefert nur
// {id: ...} des Log-Eintrags (analog Historical Evidence Lookup).
const original = $('Werte Actionability-Regeln aus').first().json;
const logId = $json.id ?? null;
return [{ json: { ...original, decision_log_id: logId } }];
